BEGIN;

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

-- ------------------------------------------------------------
-- TABEL
-- ------------------------------------------------------------

CREATE TABLE campuses (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  ptn text NOT NULL,
  prodi text NOT NULL,
  kelompok text NOT NULL DEFAULT 'Saintek',
  jenjang text NOT NULL DEFAULT 'S1',
  skor_min double precision NOT NULL,
  daya_tampung integer,
  peminat integer,
  sumber text NOT NULL DEFAULT 'manual',
  PRIMARY KEY (id),
  UNIQUE (ptn, prodi)
);

CREATE TABLE ielts_paket (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  kode text NOT NULL,
  nama text NOT NULL,
  deskripsi text,
  status text NOT NULL DEFAULT 'draft',
  mulai_at timestamptz,
  selesai_at timestamptz,
  menit_listening integer,
  menit_reading integer,
  menit_writing integer,
  menit_speaking integer,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id),
  UNIQUE (kode)
);

CREATE TABLE packages (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  kode text NOT NULL,
  nama text NOT NULL,
  deskripsi text,
  status text NOT NULL DEFAULT 'draft',
  mulai_at timestamptz,
  selesai_at timestamptz,
  acak_soal integer NOT NULL DEFAULT 0,
  tampil_pembahasan integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  jalur text NOT NULL DEFAULT 'utbk',
  siklus text,
  PRIMARY KEY (id),
  UNIQUE (kode)
);

CREATE TABLE prodi (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  nama text NOT NULL,
  ptn text NOT NULL,
  jenjang text,
  kelompok text,
  cari text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id),
  UNIQUE (nama, ptn)
);

CREATE TABLE users (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  nama text NOT NULL,
  email text NOT NULL,
  password_hash text NOT NULL,
  role text NOT NULL DEFAULT 'siswa',
  asal_sekolah text,
  no_hp text,
  target_ptn text,
  target_prodi text,
  created_at timestamptz NOT NULL DEFAULT now(),
  nama_login text,
  nisn text,
  kelas text,
  tanggal_lahir text,
  foto text,
  PRIMARY KEY (id),
  UNIQUE (email)
);

CREATE TABLE warung_paket (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  subtes text NOT NULL,
  nomor integer NOT NULL,
