CREATE TABLE attempts (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  user_id integer NOT NULL,
  package_id integer NOT NULL,
  status text NOT NULL DEFAULT 'ongoing',
  subtes_aktif text,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  total_skor double precision,
  jalur text NOT NULL DEFAULT 'utama',
  ronde integer NOT NULL DEFAULT 1,
  digugurkan_at timestamptz,
  alasan_gugur text,
  denyut_at timestamptz,
  denyut_aktif integer NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE (user_id, package_id),
  FOREIGN KEY (package_id) REFERENCES packages (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE ielts_pengerjaan (
  id integer GENERATED BY DEFAULT AS IDENTITY,
  user_id integer NOT NULL,
  paket_id integer NOT NULL,
  -- 'ongoing' | 'finished' | 'gugur'  (v21)
  status text NOT NULL DEFAULT 'ongoing',
  setuju_at timestamptz,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  -- v21: penjagaan ujian. Kembar dengan kolom senama di `attempts`.
  subtes_aktif text,
  digugurkan_at timestamptz,
  alasan_gugur text,
  denyut_at timestamptz,
  denyut_aktif integer NOT NULL DEFAULT 0,
  -- Ronde naik satu tiap kali pengelola membuka ujian susulan. Pelanggaran
  -- ronde sebelumnya tetap tersimpan sebagai bukti, hanya tidak ikut menghitung.
  ronde integer NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE (user_id, paket_id),
  FOREIGN KEY (paket_id) REFERENCES ielts_paket (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
