-- ------------------------------------------------------------
-- INDEKS
-- ------------------------------------------------------------

CREATE INDEX IF NOT EXISTS idx_ans_att ON answers(attempt_id);
CREATE INDEX IF NOT EXISTS idx_att_user ON attempts(user_id);
CREATE INDEX IF NOT EXISTS idx_campuses_jodoh ON campuses(UPPER(ptn), UPPER(prodi));
CREATE INDEX IF NOT EXISTS idx_ielts_jawaban ON ielts_jawaban(pengerjaan_id);
CREATE INDEX IF NOT EXISTS idx_ielts_nilai_guru ON ielts_nilai_guru(pengerjaan_id, subtes);
CREATE INDEX IF NOT EXISTS idx_ielts_seksi_paket ON ielts_seksi(paket_id, subtes, nomor);
CREATE INDEX IF NOT EXISTS idx_ielts_vio_kerja ON ielts_pelanggaran(pengerjaan_id, urutan);
CREATE INDEX IF NOT EXISTS idx_ielts_vio_paket ON ielts_pelanggaran(paket_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_ielts_vio_kejadian
  ON ielts_pelanggaran(pengerjaan_id, kejadian) WHERE kejadian IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ielts_soal_paket ON ielts_soal(paket_id, subtes, nomor);
CREATE INDEX IF NOT EXISTS idx_paket_siklus ON packages(siklus) WHERE siklus IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_pk_paket ON paket_kelas(package_id);
CREATE INDEX IF NOT EXISTS idx_pp_paket ON paket_peserta(package_id);
CREATE INDEX IF NOT EXISTS idx_pp_user ON paket_peserta(user_id);
CREATE INDEX IF NOT EXISTS idx_prodi_cari ON prodi(cari);
CREATE INDEX IF NOT EXISTS idx_q_pkg ON questions(package_id, subtes, nomor);
CREATE INDEX IF NOT EXISTS idx_res_att ON results(attempt_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_nama_login ON users(nama_login) WHERE nama_login IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_nisn ON users(nisn) WHERE nisn IS NOT NULL AND nisn <> '';
CREATE INDEX IF NOT EXISTS idx_vio_attempt ON violations(attempt_id, urutan);
CREATE UNIQUE INDEX IF NOT EXISTS idx_vio_kejadian ON violations(attempt_id, kejadian) WHERE kejadian IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_vio_paket ON violations(package_id);
CREATE INDEX IF NOT EXISTS idx_wjwb_sesi ON warung_jawaban(sesi_id);
CREATE INDEX IF NOT EXISTS idx_wpaket ON warung_paket(subtes, nomor);
CREATE INDEX IF NOT EXISTS idx_wsesi_papan ON warung_sesi(paket_id, status);
CREATE INDEX IF NOT EXISTS idx_wsesi_user ON warung_sesi(user_id, status);
CREATE INDEX IF NOT EXISTS idx_wsoal_paket ON warung_soal(paket_id, nomor);

