INSERT INTO packages (id, kode, nama, deskripsi, status, mulai_at, selesai_at, acak_soal, tampil_pembahasan, created_at, jalur, siklus) VALUES
  (1, 'TO-DEMO-1', 'Tryout Real UTBK-SNBT #1 — Paket Demo', 'Paket demo ADZKIA SMART. Berisi contoh butir untuk ketujuh subtes UTBK-SNBT lengkap dengan pembahasan. Dipakai untuk mencoba alur ujian, penilaian IRT, dan halaman hasil.', 'draft', NULL, NULL, 0, 1, ('2026-08-26 06:59:44'::timestamp AT TIME ZONE 'UTC'), 'utbk', NULL),
  (4, 'TO-SKD-DEMO', 'SKD Kedinasan — Paket Demo', 'Paket demo SKD Kedinasan berisi contoh butir TWK, TIU, dan TKP. Dipakai untuk mencoba alur satu sesi, penilaian poin resmi, dan passing grade. Soal karangan, bukan naskah resmi.', 'draft', NULL, NULL, 0, 1, ('2026-08-27 03:58:16'::timestamp AT TIME ZONE 'UTC'), 'skd', NULL),
  (6, 'TO-4SEP2026', 'Tryout Real UTBK-SNBT — Jumat, 4 September 2026', NULL, 'closed', ('2026-09-02T00:00'::timestamp AT TIME ZONE 'Asia/Jakarta'), ('2026-09-06T23:59'::timestamp AT TIME ZONE 'Asia/Jakarta'), 0, 1, ('2026-09-01 05:17:58'::timestamp AT TIME ZONE 'UTC'), 'utbk', '2026-09-04'),
  (9, 'TO-11SEP2026', 'Tryout Real UTBK-SNBT — Jumat, 11 September 2026', 'Disiapkan otomatis oleh penjadwal siklus pekanan. Impor naskah soalnya, lalu terbitkan.', 'draft', ('2026-09-11T00:00'::timestamp AT TIME ZONE 'Asia/Jakarta'), ('2026-09-13T23:59'::timestamp AT TIME ZONE 'Asia/Jakarta'), 0, 1, ('2026-09-10 01:25:16'::timestamp AT TIME ZONE 'UTC'), 'utbk', '2026-09-11');
